"""Smoke test: PL-02 runs end to end on the mdata.load_prices fake (shape only, no values)."""

from __future__ import annotations

import pytest

import risk.vol_pipeline
from risk.types import VolSeries
from risk.vol_pipeline import vol_series


@pytest.fixture
def fake_prices(monkeypatch: pytest.MonkeyPatch, contract_fake) -> None:
    fake = contract_fake("mdata.load_prices")
    monkeypatch.setattr(risk.vol_pipeline, "load_prices", fake.load_prices)


@pytest.mark.usefixtures("fake_prices")
def test_runs_end_to_end_with_output_shape() -> None:
    vol = vol_series("ignored.csv", window=2)
    assert isinstance(vol, VolSeries)
    assert vol.window == 2
    assert vol.returns.tickers == ("AAA", "BBB")
    assert vol.returns.base_date == "2026-01-05"
    assert len(vol.returns.dates) == 5
    assert set(vol.values) == {"AAA", "BBB"}
    for ticker in ("AAA", "BBB"):
        assert len(vol.values[ticker]) == 5
        assert vol.values[ticker][:2] == (None, None)


@pytest.mark.usefixtures("fake_prices")
def test_tickers_narrow_the_output() -> None:
    vol = vol_series("ignored.csv", window=2, tickers=["BBB"])
    assert vol.returns.tickers == ("BBB",)
    assert set(vol.values) == {"BBB"}


@pytest.mark.usefixtures("fake_prices")
def test_unknown_ticker_raises_key_error() -> None:
    with pytest.raises(KeyError):
        vol_series("ignored.csv", window=2, tickers=["ZZZ"])

